(() => {
  'use strict';

  const data = window.COMPETENCY_MAP_DATA;
  if (!data || !Array.isArray(data.groups)) return;

  const byId = new Map(
    data.groups.flatMap(group => (group.items || []).map(item => [item.id, item]))
  );

  const practiced = new Set();
  const setLesson = (id, level, note) => {
    const item = byId.get(id);
    if (!item) return;
    item.baselineLevel = Math.max(Number(item.baselineLevel) || 0, level);
    item.evidence = {
      date: '10.09.26',
      text: `Занятие: ${note}`,
      href: '10.09.26.html'
    };
    practiced.add(id);
  };

  // Десятичные дроби: разминка и повторение.
  setLesson('dec_01', 3, 'повторены разряды десятичных дробей и чтение десятых, сотых и тысячных.');
  setLesson('dec_02', 3, 'чтение десятичных дробей закреплено через связь числа знаков после запятой с названием разряда.');
  setLesson('dec_07', 3, 'сравнение десятичных дробей закреплено на примерах с нулями справа и различным положением цифр после запятой.');
  setLesson('dec_08', 3, 'закреплено, что нули справа после запятой не меняют значение числа.');
  setLesson('dec_09', 4, 'сложение десятичных дробей повторено с выравниванием по запятой.');
  setLesson('dec_10', 3, 'вычитание десятичных дробей повторено с выравниванием по запятой, дописыванием нулей и заимствованием.');
  setLesson('dec_12', 4, 'умножение десятичных дробей повторено с постановкой запятой по общему числу десятичных знаков.');
  setLesson('dec_13', 3, 'деление десятичной дроби на натуральное число закреплено на примере 1,2:3.');

  // Смысл и формы обыкновенной дроби.
  setLesson('frac_base_01', 3, 'дробь рассмотрена как часть целого.');
  setLesson('frac_base_02', 3, 'закреплены роли числителя и знаменателя.');
  setLesson('frac_base_03', 3, 'повторено распознавание правильной дроби.');
  setLesson('frac_base_04', 3, 'повторено распознавание неправильной дроби.');
  setLesson('frac_base_05', 3, 'разобрана структура смешанного числа: целая и дробная части.');
  setLesson('frac_base_06', 3, 'перевод смешанного числа в неправильную дробь многократно отработан по алгоритму.');
  setLesson('frac_base_11', 3, 'сокращение дробей отработано через общий множитель числителя и знаменателя.');

  // Действия с обыкновенными дробями.
  setLesson('frac_ops_03', 3, 'сложение дробей с разными знаменателями отработано через перекрёстные произведения и общий знаменатель.');
  setLesson('frac_ops_04', 3, 'вычитание дробей с разными знаменателями отработано по той же схеме.');
  setLesson('frac_ops_08', 3, 'умножение обыкновенных дробей закреплено как произведение числителей и произведение знаменателей.');
  setLesson('frac_ops_11', 3, 'деление дробей закреплено через замену деления умножением на обратную дробь.');
  setLesson('frac_ops_12', 3, 'действия со смешанными числами выполнялись после перевода в неправильные дроби.');

  // Делимость и разложение.
  setLesson('div_05', 3, 'разложение натуральных чисел на простые множители отработано на числах 24, 112 и 54.');
  setLesson('div_07', 4, 'признак делимости на 2 использован при последовательном разложении чётных чисел.');

  if (Array.isArray(data.repeatTopics)) {
    data.repeatTopics = data.repeatTopics.filter(id => !practiced.has(id));
  }

  data.meta.studentName = 'Ксения Васильченко';
  data.meta.updated = '10.09.2026';
  data.meta.sourceNote = 'Карта учитывает входную диагностику 06.09.26, занятие 08.09.26 и занятие 10.09.26 по десятичным и обыкновенным дробям. Уровень 4 — самостоятельное подтверждённое выполнение; уровень 3 — навык содержательно отработан на занятии и почти уверен; уровень 1 — сохраняющийся диагностический пробел; уровень 0 — пока не проверялся.';
  data.meta.material = {
    title: 'Десятичные и обыкновенные дроби',
    date: '10.09.26',
    pdf: '../pdf_docs/10.09.26.pdf',
    tex: '../tex_docs/10.09.26.tex'
  };

  const slug = value => String(value).toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[^a-z0-9а-я]+/gi, '-')
    .replace(/^-+|-+$/g, '');

  // Однократно сбрасываем прежнее локальное состояние, чтобы новая база 10.09.26
  // стала видна пользователю, затем дальнейшие ручные изменения снова сохраняются.
  const markerKey = `${data.meta.student}-competency-map-lesson-20260910-v1`;
  try {
    if (!localStorage.getItem(markerKey)) {
      const baseKey = `${data.meta.student}-${slug(data.meta.program)}`;
      localStorage.removeItem(`${baseKey}-competency-map`);
      localStorage.removeItem(`${baseKey}-repeat`);
      localStorage.setItem(markerKey, '1');
    }
  } catch (_) {}
})();